<?php
/**
 * Helper functions for rendering Pokedex entries.
 *
 * @package Primetime_Pokedex
 */

/**
 * Get post meta value for current post.
 *
 * @param string $key Meta key.
 * @return mixed Meta value.
 */
function ptp_hokepoke($key) { 
	return get_post_meta( get_the_ID(), $key, true );
}

/**
 * Check if remote file exists via HTTP HEAD request.
 *
 * @param string $url URL to check.
 * @return bool True if file exists (HTTP 200), false otherwise.
 */
function ptp_remote_file_exists($url) {
    $curl = curl_init($url);
    curl_setopt($curl, CURLOPT_NOBODY, true);
    $result = curl_exec($curl);
    $ret = false;
    if ($result !== false) {
        $statusCode = curl_getinfo($curl, CURLINFO_HTTP_CODE);  
        if ($statusCode == 200) {
            $ret = true;   
        }
    }
    curl_close($curl);
    return $ret;
}

/**
 * Render Pokemon stats block.
 *
 * @param int $atk Attack stat.
 * @param int $def Defense stat.
 * @param int $hp HP stat.
 * @param int $satk Special attack stat.
 * @param int $sdef Special defense stat.
 * @param int $spd Speed stat.
 * @return void Outputs HTML.
 */
function ptp_pokestats($atk, $def, $hp, $satk, $sdef, $spd) {
	$stats = array();
	array_push($stats, $atk, $def, $hp, $satk, $sdef, $spd);
	echo '<ul class="clean-list">';
		for($i = 0; $i < count($stats); $i++) {
			if($i == 0) 	{ $stat_title = 'HP'; $stats_class = 'hp'; }
			elseif($i == 1) { $stat_title = 'Attack'; $stats_class = 'atk'; }
			elseif($i == 2) { $stat_title = 'Defense'; $stats_class = 'def'; }
			elseif($i == 3) { $stat_title = 'S-Atk'; $stats_class = 'satk'; }
			elseif($i == 4) { $stat_title = 'S-Def'; $stats_class = 'sdef'; }
			elseif($i == 5) { $stat_title = 'Speed'; $stats_class = 'spd'; }
			$stat = $stats[$i];
			$statPerc = 150 * ($stat / 255);
			echo '<li class="poke-stats-item">';
				echo "<div class='poke-stats-bar-fill'><span class='poke-stats-$stats_class' style='height:" . esc_attr( $statPerc ) . "%;'></span></div>";
				echo '<span class="poke-stats-item-amount">' . esc_html( $stats[$i] ) . '</span>';
				echo '<span class="poke-stats-item-title">' . esc_html( $stat_title ) . '</span>';
			echo '</li>';
		}
	echo '</ul>';
}

